// --- Fetch from previous nodes ---
const input = $json; // current node (Default values)
const fromTrigger = $items('When Executed by Another Workflow')[0]?.json ?? {};

// --- Pick tags: prefer trigger input, else default ---
const tiktokTags =
  (Array.isArray(fromTrigger.tiktok_tags) && fromTrigger.tiktok_tags.length > 0)
    ? fromTrigger.tiktok_tags
    : (input.tiktok_tags_temp ?? []);

const instagramTags =
  (Array.isArray(fromTrigger.instagram_tags) && fromTrigger.instagram_tags.length > 0)
    ? fromTrigger.instagram_tags
    : (input.instagram_tags_temp ?? []);

const youtubeTags =
  (Array.isArray(fromTrigger.youtube_tags) && fromTrigger.youtube_tags.length > 0)
    ? fromTrigger.youtube_tags
    : (input.youtube_tags ?? []);

// --- Join arrays to comma-separated strings ---
const tiktok_tags = tiktokTags.join(', ');
const instagram_tags = instagramTags.join(', ');
const youtube_tags = youtubeTags.join(', ');

// --- Prefer trigger description if present ---
const description = fromTrigger.description || input.description_temp || '';

// --- Row number (if any) ---
const row_number = fromTrigger.row_number || input.row_number || null;

// --- Return updated output ---
return [
  {
    json: {
      description,
      tiktok_tags,
      instagram_tags,
      youtube_tags,
      row_number,
    },
  },
];
